class Solution:
    def minEnd(self, n, x):
        answer, remaining, bit = x, n - 1, 1
        while remaining:
            if answer & bit == 0:
                if remaining & 1:
                    answer |= bit
                remaining >>= 1
            bit <<= 1
        return answer

